{
  "capability": "production-scheduling",
  "version": "1.0.0",
  "scenarios": [
    {
      "id": "PSC-001",
      "name": "Basic job priority sequencing with EDD rule",
      "difficulty": "easy",
      "category": "job-sequencing",
      "context": {
        "situation": "You are the production scheduler at Meridian Machining, a contract job shop with 45 employees. Your CNC turning centre (the constraint, running 2 shifts at 16 hours/day) has 5 jobs queued for today. No sequence-dependent setups — all changeovers are 20 minutes flat. You need to sequence these jobs for the day shift (8 hours available). All materials are staged and operators are available.",
        "available_data": {
          "jobs": [
            {"work_order": "WO-3301", "product": "Shaft Assembly SA-100", "processing_time_hrs": 2.0, "due_date": "2025-09-18", "customer": "Apex Motors", "customer_tier": 2},
            {"work_order": "WO-3302", "product": "Valve Body VB-220", "processing_time_hrs": 3.5, "due_date": "2025-09-17", "customer": "FlowTech Industries", "customer_tier": 3},
            {"work_order": "WO-3303", "product": "Gear Housing GH-55", "processing_time_hrs": 1.5, "due_date": "2025-09-19", "customer": "Summit Drivetrain", "customer_tier": 1},
            {"work_order": "WO-3304", "product": "Pump Cover PC-80", "processing_time_hrs": 1.0, "due_date": "2025-09-17", "customer": "HydraForce LLC", "customer_tier": 3},
            {"work_order": "WO-3305", "product": "Bearing Cap BC-12", "processing_time_hrs": 2.5, "due_date": "2025-09-18", "customer": "Precision Bearings", "customer_tier": 2}
          ],
          "today": "2025-09-16",
          "available_hours_day_shift": 8.0,
          "changeover_time_min": 20,
          "constraint_work_centre": "CNC Turning Centre TC-01"
        }
      },
      "task": "Determine the optimal job sequence for the day shift. Show your prioritisation logic, calculate whether all jobs can be completed in the shift, and identify any jobs that must be deferred to the evening shift.",
      "evaluation_criteria": [
        {
          "criterion": "dispatching_rule_selection",
          "weight": 0.30,
          "rubric": {
            "pass": "Selects EDD (Earliest Due Date) as the primary dispatching rule since the goal is meeting delivery commitments. Correctly identifies WO-3302 and WO-3304 as the most urgent (both due 9/17). May also note that customer tier could be used as a tiebreaker.",
            "fail": "Uses FIFO or random sequencing. Selects SPT without acknowledging the due date urgency. Does not explain the rationale for the chosen rule."
          }
        },
        {
          "criterion": "capacity_calculation",
          "weight": 0.30,
          "rubric": {
            "pass": "Calculates total processing time: 2.0 + 3.5 + 1.5 + 1.0 + 2.5 = 10.5 hours. Adds changeover time: 4 changeovers × 20 min = 80 min = 1.33 hours. Total required: 11.83 hours. Available: 8 hours on day shift. Correctly identifies that not all jobs fit in the day shift and specifies which jobs defer to evening.",
            "fail": "Ignores changeover time. Claims all jobs fit in 8 hours. Gets the arithmetic wrong by more than 30 minutes."
          }
        },
        {
          "criterion": "sequence_logic",
          "weight": 0.25,
          "rubric": {
            "pass": "Sequences due-9/17 jobs first (WO-3302 and WO-3304), then due-9/18 jobs (WO-3301 and WO-3305), then WO-3303 (due 9/19). Uses customer tier as tiebreaker for same-due-date jobs. Identifies that the day shift can complete approximately 3–4 jobs and the remainder defers.",
            "fail": "Sequences jobs randomly or by processing time alone without considering due dates. Puts the 9/19 job before the 9/17 jobs."
          }
        },
        {
          "criterion": "practical_judgment",
          "weight": 0.15,
          "rubric": {
            "pass": "Notes that WO-3303 (Tier-1 customer Summit Drivetrain) has the latest due date and can safely defer. May recommend checking if the evening shift can handle all deferred work. May note that the Tier-1 customer's job should be monitored even though its due date gives slack.",
            "fail": "Does not mention customer tier considerations. Does not address what happens to deferred jobs."
          }
        }
      ]
    },
    {
      "id": "PSC-002",
      "name": "OEE calculation and loss prioritisation at the constraint",
      "difficulty": "easy",
      "category": "oee-analysis",
      "context": {
        "situation": "You are reviewing the weekly OEE data for the constraint work centre (Injection Moulding Machine #3) at Polaris Plastics, a manufacturer of automotive interior components. The plant manager wants to understand where capacity is being lost and which improvement should be prioritised.",
        "available_data": {
          "scheduled_production_time_hrs": 120,
          "planned_downtime_hrs": 8,
          "unplanned_downtime_hrs": 14,
          "ideal_cycle_time_seconds": 45,
          "total_pieces_produced": 7200,
          "good_pieces": 6840,
          "operating_time_hrs": 98,
          "constraint_throughput_value_per_hour": 650
        }
      },
      "task": "Calculate the OEE components (Availability, Performance, Quality) and overall OEE. Identify the largest loss category, quantify the financial impact, and recommend the top improvement priority.",
      "evaluation_criteria": [
        {
          "criterion": "oee_calculation",
          "weight": 0.35,
          "rubric": {
            "pass": "Correctly calculates: Planned Production Time = 120 - 8 = 112 hrs. Availability = (112 - 14) / 112 = 98/112 = 87.5%. Performance = (45 × 7200) / (98 × 3600) = 324,000 / 352,800 = 91.8%. Quality = 6840/7200 = 95.0%. OEE = 0.875 × 0.918 × 0.95 = 76.3% (approximately). Acceptable range: 74–78%.",
            "fail": "Includes planned downtime in the availability loss. Gets the performance calculation wrong (uses scheduled time instead of operating time). Omits one of the three OEE components."
          }
        },
        {
          "criterion": "loss_identification",
          "weight": 0.30,
          "rubric": {
            "pass": "Identifies unplanned downtime (14 hours, availability loss) as the single largest loss category. Quantifies: 14 hours × $650/hr = $9,100/week in lost constraint throughput. May also note that performance losses represent ~8% gap from ideal (equivalent to ~8 hours) and quality losses represent 360 rejected pieces.",
            "fail": "Identifies the wrong loss category as primary. Does not quantify the financial impact. Confuses planned and unplanned downtime."
          }
        },
        {
          "criterion": "improvement_recommendation",
          "weight": 0.20,
          "rubric": {
            "pass": "Recommends prioritising unplanned downtime reduction at the constraint (e.g., preventive maintenance, TPM daily checks, breakdown analysis). Notes that this is the constraint — every hour of downtime reduction directly translates to throughput gain. May reference the TOC principle of exploiting the constraint.",
            "fail": "Recommends improving quality or performance first without justifying why over availability. Suggests generic 'continuous improvement' without targeting the constraint."
          }
        },
        {
          "criterion": "contextual_awareness",
          "weight": 0.15,
          "rubric": {
            "pass": "Notes that 76% OEE is above typical discrete manufacturing (55–65%) but below world-class (85%+). Recognises that because this is the constraint, OEE improvement here has a 1:1 relationship with plant throughput improvement. May note that improving non-constraint OEE would not increase plant output.",
            "fail": "Does not contextualise the OEE result. Treats it as an isolated number without connecting to plant throughput."
          }
        }
      ]
    },
    {
      "id": "PSC-003",
      "name": "Critical ratio calculation and job prioritisation",
      "difficulty": "easy",
      "category": "job-sequencing",
      "context": {
        "situation": "You are the scheduler at Cascade Manufacturing on a Monday morning. You need to prioritise 4 jobs at the grinding work centre based on critical ratio. Current date is Monday, September 22, 2025.",
        "available_data": {
          "jobs": [
            {"work_order": "WO-5501", "product": "Camshaft CS-18", "due_date": "2025-09-26", "remaining_processing_days": 3.0, "customer": "ValveTech"},
            {"work_order": "WO-5502", "product": "Crankshaft CK-44", "due_date": "2025-09-24", "remaining_processing_days": 3.5, "customer": "MotorWorks"},
            {"work_order": "WO-5503", "product": "Piston Pin PP-07", "due_date": "2025-09-30", "remaining_processing_days": 2.0, "customer": "Precision Engines"},
            {"work_order": "WO-5504", "product": "Rocker Arm RA-22", "due_date": "2025-09-25", "remaining_processing_days": 1.5, "customer": "Summit Auto"}
          ],
          "current_date": "2025-09-22"
        }
      },
      "task": "Calculate the critical ratio for each job, rank them by priority, and recommend the processing sequence. Identify any jobs that are behind schedule and need escalation.",
      "evaluation_criteria": [
        {
          "criterion": "critical_ratio_calculation",
          "weight": 0.40,
          "rubric": {
            "pass": "Correctly calculates CR for each: WO-5501: (Sep 26 - Sep 22)/3.0 = 4/3.0 = 1.33. WO-5502: (Sep 24 - Sep 22)/3.5 = 2/3.5 = 0.57. WO-5503: (Sep 30 - Sep 22)/2.0 = 8/2.0 = 4.0. WO-5504: (Sep 25 - Sep 22)/1.5 = 3/1.5 = 2.0. Acceptable rounding within ±0.05.",
            "fail": "Gets the date arithmetic wrong. Inverts the CR formula. Calculates CR using business days when the data implies calendar days, without noting the assumption."
          }
        },
        {
          "criterion": "priority_ranking",
          "weight": 0.30,
          "rubric": {
            "pass": "Ranks by ascending CR: WO-5502 (0.57) → WO-5501 (1.33) → WO-5504 (2.0) → WO-5503 (4.0). Correctly identifies WO-5502 as critically behind schedule (CR < 1.0) and flags it for immediate processing and escalation.",
            "fail": "Ranks by descending CR (wrong — lower CR = higher urgency). Does not identify WO-5502 as behind schedule."
          }
        },
        {
          "criterion": "escalation_judgment",
          "weight": 0.30,
          "rubric": {
            "pass": "Flags WO-5502 (CR = 0.57) as critically behind schedule — it needs 3.5 days of work but has only 2 days until due date. Recommends escalation: overtime, alternate routing, or customer notification of likely delay. May note that WO-5503 (CR = 4.0) has significant slack and could be deferred if needed.",
            "fail": "Does not identify the behind-schedule job or recommend escalation. Treats all jobs as equally manageable."
          }
        }
      ]
    },
    {
      "id": "PSC-004",
      "name": "Simple changeover sequence optimisation on a paint line",
      "difficulty": "easy",
      "category": "changeover-optimisation",
      "context": {
        "situation": "You are scheduling a batch paint line at Atlas Coatings. Today's production requires painting 5 batches of parts in different colours. The setup matrix shows that light-to-dark transitions require only a brief flush (10 minutes), while dark-to-light transitions require a full purge (35 minutes). Same-family transitions are 15 minutes. All batches have the same due date (end of day), so sequence is purely about minimising changeover time.",
        "available_data": {
          "batches": [
            {"batch": "B1", "colour": "Black", "run_time_hrs": 1.5},
            {"batch": "B2", "colour": "White", "run_time_hrs": 2.0},
            {"batch": "B3", "colour": "Red", "run_time_hrs": 1.0},
            {"batch": "B4", "colour": "Yellow", "run_time_hrs": 1.5},
            {"batch": "B5", "colour": "Blue", "run_time_hrs": 1.0}
          ],
          "setup_matrix_minutes": {
            "light_to_dark": 10,
            "dark_to_light": 35,
            "same_family": 15
          },
          "colour_order_light_to_dark": ["White", "Yellow", "Red", "Blue", "Black"]
        }
      },
      "task": "Determine the optimal colour sequence to minimise total changeover time. Calculate the total changeover time for your recommended sequence and compare it to the worst-case sequence.",
      "evaluation_criteria": [
        {
          "criterion": "optimal_sequence",
          "weight": 0.40,
          "rubric": {
            "pass": "Recommends a light-to-dark sequence: White → Yellow → Red → Blue → Black (or similar ordering respecting the light-to-dark gradient). Total changeovers: 4 transitions × 10 min = 40 minutes. Recognises that this is the minimum achievable changeover time.",
            "fail": "Recommends a random or dark-to-light sequence. Does not recognise the light-to-dark sequencing principle."
          }
        },
        {
          "criterion": "worst_case_comparison",
          "weight": 0.25,
          "rubric": {
            "pass": "Identifies the worst case as dark-to-light (Black → Blue → Red → Yellow → White), producing 4 transitions × 35 min = 140 minutes. Quantifies the savings: 140 - 40 = 100 minutes saved, representing 1.67 hours of additional production capacity.",
            "fail": "Does not compare to the worst case. Cannot quantify the benefit of the optimised sequence."
          }
        },
        {
          "criterion": "setup_matrix_understanding",
          "weight": 0.20,
          "rubric": {
            "pass": "Demonstrates understanding that changeover time is sequence-dependent (not fixed) and that the setup matrix drives the optimisation. Correctly applies the light-to-dark vs. dark-to-light cost asymmetry.",
            "fail": "Treats all changeovers as equal time. Does not reference the setup matrix."
          }
        },
        {
          "criterion": "practical_notes",
          "weight": 0.15,
          "rubric": {
            "pass": "Notes that this optimisation applies only when due dates are equal. If due dates differed, a due-date-constrained job might need to be inserted out of colour order, accepting the changeover penalty. May also note that the last run (Black) positions the line for a dark start the next day.",
            "fail": "Presents the solution as universally applicable without noting the due date assumption."
          }
        }
      ]
    },
    {
      "id": "PSC-005",
      "name": "Identifying the true constraint from WIP and utilisation data",
      "difficulty": "easy",
      "category": "bottleneck-management",
      "context": {
        "situation": "You are reviewing production data at Fortis Assembly, an electronics contract manufacturer. The plant manager asks you to identify the bottleneck. You have utilisation data for 4 work centres and WIP queue information. There is a common misconception on the floor that soldering is the bottleneck because 'there's always a pile of boards in front of it.'",
        "available_data": {
          "work_centres": [
            {"name": "SMT Pick-and-Place", "utilisation_pct": 92, "wip_queue_units": 120, "avg_cycle_time_min": 4.5},
            {"name": "Wave Soldering", "utilisation_pct": 78, "wip_queue_units": 340, "avg_cycle_time_min": 3.0},
            {"name": "Manual Assembly", "utilisation_pct": 65, "wip_queue_units": 50, "avg_cycle_time_min": 8.0},
            {"name": "Testing & QC", "utilisation_pct": 71, "wip_queue_units": 80, "avg_cycle_time_min": 5.0}
          ],
          "daily_demand_units": 180,
          "shift_hours": 16
        }
      },
      "task": "Identify the true constraint (bottleneck), explain why the WIP pile at wave soldering is misleading, and recommend constraint management actions.",
      "evaluation_criteria": [
        {
          "criterion": "constraint_identification",
          "weight": 0.35,
          "rubric": {
            "pass": "Correctly identifies SMT Pick-and-Place as the true constraint based on its 92% utilisation — the highest among all work centres. Explains that utilisation ratio (load vs. available capacity) determines the constraint, not WIP queue size.",
            "fail": "Identifies wave soldering as the bottleneck based on the WIP pile. Identifies manual assembly based on longest cycle time."
          }
        },
        {
          "criterion": "wip_misconception_explanation",
          "weight": 0.30,
          "rubric": {
            "pass": "Explains that WIP piles up at soldering because SMT (the upstream constraint) batch-releases boards in bursts when it completes a run, overwhelming soldering's queue temporarily. Soldering at 78% utilisation has excess capacity to clear the queue — it just receives work in lumps rather than continuously. The WIP is a symptom of upstream batching, not of soldering being overloaded.",
            "fail": "Cannot explain the WIP misconception. Accepts the WIP pile as evidence of a bottleneck."
          }
        },
        {
          "criterion": "constraint_management_recommendations",
          "weight": 0.35,
          "rubric": {
            "pass": "Recommends TOC-based actions: exploit the SMT constraint (minimise changeovers, eliminate micro-stops, run through breaks with relief operator), subordinate other work centres to SMT's pace, establish a buffer before SMT to prevent starvation. May note that improving soldering or testing would not increase plant output since SMT is the constraint.",
            "fail": "Recommends adding capacity at soldering. Suggests improving all work centres equally without prioritising the constraint."
          }
        }
      ]
    },
    {
      "id": "PSC-006",
      "name": "Forward and backward scheduling for a multi-operation work order",
      "difficulty": "easy",
      "category": "job-sequencing",
      "context": {
        "situation": "You are scheduling a new work order (WO-7010) for a gearbox housing at Pioneer Manufacturing. The work order has 4 operations with known processing times. Material is available today (Monday, September 22). Customer due date is Friday, September 26. The plant runs one 8-hour shift per day, Monday through Friday.",
        "available_data": {
          "work_order": "WO-7010",
          "product": "Gearbox Housing GH-200",
          "operations": [
            {"op": 10, "work_centre": "CNC Milling", "setup_hrs": 0.5, "run_hrs": 6.0},
            {"op": 20, "work_centre": "Deburring", "setup_hrs": 0.0, "run_hrs": 2.0},
            {"op": 30, "work_centre": "Heat Treatment", "setup_hrs": 1.0, "run_hrs": 4.0},
            {"op": 40, "work_centre": "Final Inspection", "setup_hrs": 0.0, "run_hrs": 1.5}
          ],
          "material_available_date": "2025-09-22",
          "customer_due_date": "2025-09-26",
          "shift_hours_per_day": 8,
          "work_days": ["Mon", "Tue", "Wed", "Thu", "Fri"]
        }
      },
      "task": "Perform both forward scheduling (from material availability) and backward scheduling (from due date). Determine the earliest completion date and latest start date. Assess whether the work order can be completed on time and identify the float (slack).",
      "evaluation_criteria": [
        {
          "criterion": "forward_schedule",
          "weight": 0.30,
          "rubric": {
            "pass": "Correctly calculates forward schedule: Op 10 = 6.5 hrs (Mon), Op 20 = 2.0 hrs (starts Tue, need to account for Op 10 spilling into Tue if day is 8 hrs — Op 10 is 6.5 hrs, fits in Mon). Op 20 fits Tue morning (2 hrs). Op 30 starts Tue (5 hrs, spills to Wed or fits depending on calculation). Op 40 = 1.5 hrs. Total processing = 15 hours = roughly 2 full days. Earliest completion is approximately Wednesday or Thursday depending on assumptions about inter-operation queue time. Range: Wed PM to Thu AM is acceptable.",
            "fail": "Ignores setup times. Assumes all operations can run simultaneously. Gets the total processing time wrong by more than 2 hours."
          }
        },
        {
          "criterion": "backward_schedule",
          "weight": 0.30,
          "rubric": {
            "pass": "Works backward from Friday (due date): Op 40 (1.5 hrs) must finish by end of Friday → starts Fri at 6:30 AM. Op 30 (5 hrs) must finish before Op 40 starts → latest finish Thu end-of-day, start Thu at 3:00 AM (which is before shift start) or Wed PM. Working backward, the latest start date for Op 10 is approximately Tuesday or Wednesday. Shows that there is float between the forward schedule (finish Wed/Thu) and due date (Friday).",
            "fail": "Does not perform backward scheduling. Confuses forward and backward logic."
          }
        },
        {
          "criterion": "float_assessment",
          "weight": 0.25,
          "rubric": {
            "pass": "Correctly identifies that the job has approximately 1–2 days of float (forward completion Wed/Thu vs. due date Friday). Notes that this float provides buffer against disruptions. May recommend using the float strategically — e.g., scheduling the job later to reduce WIP if the constraint is not involved.",
            "fail": "Cannot calculate float. Claims the job is at risk when there is significant slack, or claims there is no risk when the job is tight."
          }
        },
        {
          "criterion": "scheduling_awareness",
          "weight": 0.15,
          "rubric": {
            "pass": "Notes the difference between forward and backward scheduling applications: forward scheduling finds the earliest completion, backward scheduling preserves flexibility and minimises WIP. May recommend backward scheduling as the default to avoid early starts that tie up WIP unnecessarily.",
            "fail": "Does not explain the practical difference between forward and backward scheduling."
          }
        }
      ]
    },
    {
      "id": "PSC-007",
      "name": "Labour skill matrix and shift coverage gap analysis",
      "difficulty": "easy",
      "category": "labour-scheduling",
      "context": {
        "situation": "You are reviewing the night shift staffing plan at Stellar Components. The night shift runs 3 production lines. Each line requires at least one operator with the appropriate certification. You need to assess whether tonight's scheduled crew can cover all lines and identify any single-point-of-failure risks.",
        "available_data": {
          "production_lines": [
            {"line": "CNC Lathe Cell", "certification_required": "CNC-L2", "scheduled_jobs": 3},
            {"line": "Welding Station", "certification_required": "AWS-D1.1", "scheduled_jobs": 2},
            {"line": "Surface Grinding", "certification_required": "GRND-1", "scheduled_jobs": 4}
          ],
          "night_shift_operators": [
            {"name": "A. Martinez", "certifications": ["CNC-L2", "GRND-1"]},
            {"name": "B. Jackson", "certifications": ["AWS-D1.1"]},
            {"name": "C. Patel", "certifications": ["CNC-L2", "AWS-D1.1", "GRND-1"]},
            {"name": "D. Kim", "certifications": ["GRND-1"]},
            {"name": "E. Thompson", "certifications": ["CNC-L2"]}
          ]
        }
      },
      "task": "Assign operators to lines, identify any single-point-of-failure certifications, and recommend cross-training priorities to reduce risk.",
      "evaluation_criteria": [
        {
          "criterion": "operator_assignment",
          "weight": 0.30,
          "rubric": {
            "pass": "Provides a feasible assignment covering all 3 lines. For example: Martinez → CNC Lathe, Jackson → Welding, Patel or Kim → Grinding. Notes that Patel is the most versatile operator and should be reserved as a floater/backup rather than locked to a single line.",
            "fail": "Assigns an operator to a line they are not certified for. Leaves a line uncovered."
          }
        },
        {
          "criterion": "single_point_of_failure_identification",
          "weight": 0.40,
          "rubric": {
            "pass": "Identifies AWS-D1.1 (Welding) as the critical single-point-of-failure: only Jackson and Patel hold this certification on night shift. If both are absent, welding cannot run. CNC-L2 has 3 certified operators (lower risk). GRND-1 has 3 certified operators (lower risk). Welding certification is the highest-risk gap.",
            "fail": "Does not identify the single-point-of-failure. Treats all certifications as equally covered."
          }
        },
        {
          "criterion": "cross_training_recommendation",
          "weight": 0.30,
          "rubric": {
            "pass": "Recommends cross-training at least one additional operator in AWS-D1.1 (welding) as the top priority. Suggests Martinez or Thompson as candidates (they already have CNC certification, welding would make them more versatile). Quantifies the risk: with only 2 welding-certified operators, any absence disables the line.",
            "fail": "Recommends cross-training generically without identifying welding as the priority."
          }
        }
      ]
    },
    {
      "id": "PSC-008",
      "name": "Drum-buffer-rope implementation for a new constraint",
      "difficulty": "medium",
      "category": "bottleneck-management",
      "context": {
        "situation": "You are the production scheduler at Vanguard Metal Works, a manufacturer of precision aerospace components. The plant recently added a new titanium machining centre that has become the constraint due to high demand for titanium parts. The upstream operations are sawing (2 saws, 85% utilisation), heat treatment (batch furnace, 60% utilisation), and CNC rough machining (3 machines, 72% utilisation). Downstream is finishing (2 grinders, 68% utilisation) and inspection (55% utilisation). The titanium machining centre runs at 94% utilisation, processing 40 parts per day. The upstream lead time from sawing to the titanium centre is approximately 12 hours. You have been asked to implement drum-buffer-rope for this new constraint.",
        "available_data": {
          "constraint": {
            "work_centre": "Titanium Machining Centre TMC-01",
            "utilisation_pct": 94,
            "daily_output": 40,
            "cycle_time_min": 12,
            "available_hrs_per_day": 16,
            "planned_changeovers_per_day": 3,
            "changeover_time_min": 25
          },
          "upstream_lead_time_hrs": 12,
          "upstream_reliability": "moderate — sawing occasionally has blade breakages, heat treatment has ±1 hour cycle variability",
          "work_centres": [
            {"name": "Sawing", "utilisation_pct": 85, "machines": 2},
            {"name": "Heat Treatment", "utilisation_pct": 60, "machines": 1},
            {"name": "CNC Rough Machining", "utilisation_pct": 72, "machines": 3},
            {"name": "Titanium Machining Centre", "utilisation_pct": 94, "machines": 1},
            {"name": "Finishing/Grinding", "utilisation_pct": 68, "machines": 2},
            {"name": "Final Inspection", "utilisation_pct": 55, "machines": 1}
          ]
        }
      },
      "task": "Design a drum-buffer-rope system for this plant. Specify the drum schedule, buffer size and monitoring zones, rope mechanism, and exploitation actions to maximise throughput at the titanium machining centre.",
      "evaluation_criteria": [
        {
          "criterion": "drum_identification_and_exploitation",
          "weight": 0.30,
          "rubric": {
            "pass": "Correctly identifies TMC-01 as the drum. Proposes specific exploitation actions: reduce changeovers (SMED on the 3 daily changeovers, target 15 min each to recover 30 min/day), run through breaks with relief operator, pre-inspect parts before they reach the constraint (quality gate upstream), pre-stage tooling and programs. Quantifies: at 12 min/cycle, each saved minute = ~5 additional parts/day. Reducing changeovers by 30 min = ~2.5 extra parts/day.",
            "fail": "Identifies the constraint but provides no specific exploitation actions. Recommends buying another machine before exploiting the existing one."
          }
        },
        {
          "criterion": "buffer_design",
          "weight": 0.30,
          "rubric": {
            "pass": "Sets a time buffer at 50% of upstream lead time (12 hrs × 0.5 = 6 hours) given moderate upstream reliability. Defines buffer zones: Green (0–2 hrs consumed), Yellow (2–4 hrs), Red (4–6 hrs). Specifies monitoring actions for each zone. May note that the buffer should be calibrated over 2–4 weeks of observation.",
            "fail": "Sets no buffer or an arbitrary buffer without relating it to upstream lead time. Does not define monitoring zones."
          }
        },
        {
          "criterion": "rope_mechanism",
